"""G-equivariant CNN primitives for the chess symmetry groups.

Supported groups:
    * ``GCHESS_GROUP`` (default) — the full G_chess = Z/2 x Z/2 with
      elements (E, sigma_h, sigma_c, sigma_hc).
    * ``SGCHESS_GROUP`` — the SG_chess subgroup ~ Z/2 generated by
      sigma_c (color swap + rank flip). Local enumeration (E, sigma_c).
    * ``FLIPGROUP_GROUP`` — the FlipGroup subgroup ~ Z/2 generated by
      sigma_h (file flip). Local enumeration (E, sigma_h).

Each primitive accepts a ``group: GroupDef`` keyword (default
``GCHESS_GROUP``) so the same building blocks can construct either a
full-group model or a subgroup-only model. The number of group fibers is
``group.order`` — 4 for GChess, 2 for the two subgroups.

G-signal storage convention:
    folded layout ``(B, C * |G|, H, W)`` — compatible with standard
    ``Conv2d`` / ``BatchNorm2d``. Within the channel axis, channel-major
    ordering: position ``(logical_c, g_idx)`` lives at folded index
    ``logical_c * |G| + g_idx``, so each logical channel's |G| group
    copies are contiguous.

The action of group element ``g`` on a G-signal is:
    1. Spatial flip per ``g`` (file flip / rank flip / both / none) —
       given by the corresponding GChess element via ``group.to_gchess``
       and resolved by ``symmetry.actions.group_action_output``.
    2. Channel permutation following the regular representation:
       ``new[c*|G|+h] = old[c*|G| + group.compose(g, h)]``. For our
       self-inverse groups this is the same as
       ``old[c*|G| + group.compose(g^{-1}, h)]``.

Primitives:
    LiftingConv : Z^2 signal (B, 34, H, W)            -> G signal (B, C_out * |G|, H, W)
    GConv       : G signal (B, C_in * |G|, H, W)      -> G signal (B, C_out * |G|, H, W)
    GLinear     : G "1x1" signal (B, C_in * |G|)      -> G "1x1" signal (B, C_out * |G|)
    GBatchNorm  : G signal in/out, with stats SHARED across the |G|
                  copies of each logical channel (see note below).
    GSELayer    : equivariant SE block built from GLinear + element-wise
                  gating, broadcast spatially.

NOTE on GBatchNorm — BN statistics and affine parameters are SHARED
across the |G| copies of each logical channel (pooled over the group
fiber as well as batch and space). Strict equivariance of the network
after training requires them to be EQUAL across the copies. Stored
separately they would diverge during training, because the training
distribution is canonicalised (only one orbit of each position is ever
observed), and ``equivariance_error(GCNNChess) < 1e-5`` would fail.
Sharing is also the standard equivariant-CNN practice (escnn,
Cohen & Welling).
"""

from __future__ import annotations

from typing import List, Optional

import torch
import torch.nn as nn
import torch.nn.functional as F

from symmetry.actions import group_action_output as _spatial_action
from symmetry.group import (
    COMPOSITION_TABLE,
    FLIPGROUP_GROUP,
    GCHESS_GROUP,
    GChess,
    GroupDef,
    ORDER as GROUP_SIZE,
    SGCHESS_GROUP,
)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _spatial_g(g_chess_int: int, t: torch.Tensor) -> torch.Tensor:
    """Apply the spatial part of a GChess element to a tensor whose last
    two dims are (H, W). Channels and any preceding dims are unstructured.

    Re-uses ``symmetry.actions.group_action_output`` so the spatial action
    matches symmetry.actions exactly. The argument is a *GChess* element integer
    (E / SIGMA_H / SIGMA_C / SIGMA_HC) — primitives that work with a
    generic ``GroupDef`` translate their local indices to GChess via
    ``group.gchess_element(local_g)`` before calling this helper.
    """
    return _spatial_action(g_chess_int, t)


def regular_rep_perm(
    local_g: int,
    num_logical_channels: int,
    group: GroupDef = GCHESS_GROUP,
) -> torch.Tensor:
    """Channel permutation for the regular representation acting on a
    folded G-signal ``(B, C*|G|, H, W)`` with channel-major ordering.

    Returns a ``(C * |G|,)`` LongTensor ``perm`` such that
        ``out[c*|G|+h] = in[perm[c*|G|+h]] = in[c*|G| + group.compose(g, h)]``
    is the regular representation's action on the channel axis.

    ``local_g`` is the index of an element within ``group`` (NOT a
    GChess element index, unless ``group is GCHESS_GROUP`` in which case
    they coincide).
    """
    order = group.order
    perm = torch.empty(num_logical_channels * order, dtype=torch.long)
    g_int = int(local_g)
    table = group.composition_table
    for c in range(num_logical_channels):
        for h in range(order):
            perm[c * order + h] = c * order + table[g_int][h]
    return perm


def group_action_g_signal(
    local_g,
    x: torch.Tensor,
    num_logical_channels: int,
    group: GroupDef = GCHESS_GROUP,
) -> torch.Tensor:
    """Apply group element ``local_g`` to a folded G-signal
    ``(B, C*|G|, H, W)``.

    Equivariance checks should compare
        ``layer(group_action_g_signal(g, x))``
    against
        ``group_action_g_signal(g, layer(x))``.
    """
    order = group.order
    if x.shape[1] != num_logical_channels * order:
        raise ValueError(
            f"channel count {x.shape[1]} does not match "
            f"{num_logical_channels} * {order} = "
            f"{num_logical_channels * order}"
        )
    gchess_int = group.gchess_element(int(local_g))
    spatial = _spatial_g(gchess_int, x)
    perm = regular_rep_perm(local_g, num_logical_channels, group).to(spatial.device)
    return spatial.index_select(dim=1, index=perm)


# ---------------------------------------------------------------------------
# LiftingConv: chess Z^2 input (34, H, W) -> G signal (C_out * |G|, H, W)
# ---------------------------------------------------------------------------


class LiftingConv(nn.Module):
    """Group-equivariant lifting layer specialized for the 34-plane
    chess input. Supports both GCHESS_GROUP and SGCHESS_GROUP.

    Construction (one base kernel + ``|G|-1`` chess-aware copies).
    Start with a single base kernel ``K`` of shape
    ``(C_out, 34, k, k)``. The Conv2d weight applied at forward time
    stacks ``|G|`` kernels — one per local group element ``g`` — built
    by applying ``g``'s full chess action to ``K``:

        - For the GChess element ``e``: ``K`` (identity).
        - For ``sigma_h``: ``spatial_file_flip(K)``.
        - For ``sigma_c``: ``spatial_rank_flip(K[:, sigma_c_perm]) * sign_sigma_c``.
        - For ``sigma_hc``: ``spatial_both_flip(K[:, sigma_c_perm]) * sign_sigma_c``.

    where ``sigma_c_perm = SIGMA_C_CHANNEL_PERM`` (us<->opp + castling
    swap), and ``sign_sigma_c`` is the 34-entry vector with -1 at index
    30 (the plane-30 sign flip) and +1 elsewhere. The stacked Conv2d
    weight has shape ``(C_out * |G|, 34, k, k)`` in c-major folding
    (logical channel ``c``'s |G| group copies occupy contiguous indices
    ``c*|G| + g``).

    Equivariance.
    Under the FULL chess action on the input (``group_action_input(g, x)``
    from ``symmetry.actions`` — spatial flip + sigma_c channel
    permutation + plane-30 sign flip), the output transforms as the
    standard G-signal action (``group_action_g_signal``: regular
    representation on the group axis + spatial flip on H, W).

    Sketch: ``conv(K, sigma_c(x))(c, r, f) = conv(sigma_c_kernel(K), x)(c, 7-r, f)``
    by the substitution ``j = sigma_c_perm(i), dr' = -dr`` — the channel
    permutation and plane-30 sign on the *input* ``x`` are exactly
    absorbed into the corresponding kernel transformation for the
    sigma_c output slice, so the equivariance holds independently of
    padding edge effects.

    Bias is per logical output channel, broadcast across the |G| group
    copies — equivariant under the regular representation.

    Constraint: ``in_channels`` must be exactly 34 (the chess plane
    layout). The layer is chess-specific by construction; a
    generic-rank Z^2 lifting layer doesn't apply here.

    For ``group = SGCHESS_GROUP``, only two output slices are built
    (``e`` and ``sigma_c``), giving a ``(C_out * 2, 34, k, k)`` weight.
    The chess-aware kernel transformations are identical to the GChess
    case — they only depend on which GChess element each slice
    corresponds to (looked up via ``group.to_gchess``).
    """

    IN_CHANNELS = 34  # the chess 34-plane layout

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        padding: int = 0,
        bias: bool = True,
        group: GroupDef = GCHESS_GROUP,
    ):
        super().__init__()
        if in_channels != self.IN_CHANNELS:
            raise ValueError(
                f"LiftingConv is chess-specific: in_channels must be "
                f"{self.IN_CHANNELS}, got {in_channels}"
            )
        self.group = group
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.padding = padding

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size, kernel_size)
        )
        nn.init.kaiming_normal_(self.weight, nonlinearity="relu")
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter("bias", None)

        # Buffers for the chess input action: sigma_c channel permutation
        # and the plane-30 sign vector. Registered as buffers so they
        # move with ``.to(device)`` automatically.
        from symmetry.actions import SIGMA_C_CHANNEL_PERM

        chan_perm = torch.tensor(SIGMA_C_CHANNEL_PERM, dtype=torch.long)
        self.register_buffer("sigma_c_chan_perm", chan_perm, persistent=False)
        sign_vec = torch.ones(in_channels)
        sign_vec[30] = -1.0
        # Reshape so it broadcasts over (C_out, ., k, k) when multiplied.
        self.register_buffer(
            "sigma_c_sign", sign_vec.view(1, in_channels, 1, 1), persistent=False
        )

    def _apply_gchess_to_kernel(self, gchess_int: int) -> torch.Tensor:
        """Apply a GChess element's chess input action to the base kernel.

        ``gchess_int`` is a value from ``GChess`` (E / SIGMA_H / SIGMA_C
        / SIGMA_HC). The kernel transformation here is the SAME as the
        chess input action — that's the whole point of this construction
        (so the input action gets absorbed into the kernel)."""
        K = self.weight
        if gchess_int == int(GChess.E):
            return K
        if gchess_int == int(GChess.SIGMA_H):
            return torch.flip(K, dims=[-1])
        # sigma_c and sigma_hc both include channel perm + plane-30 sign flip.
        K_perm = K.index_select(dim=1, index=self.sigma_c_chan_perm)
        K_signed = K_perm * self.sigma_c_sign.to(K.dtype)
        if gchess_int == int(GChess.SIGMA_C):
            return torch.flip(K_signed, dims=[-2])
        if gchess_int == int(GChess.SIGMA_HC):
            return torch.flip(K_signed, dims=[-2, -1])
        raise ValueError(f"unknown GChess element {gchess_int}")

    def _build_kernel(self) -> torch.Tensor:
        """Stack the |G| chess-action-transformed kernels into a single
        ``(C_out * |G|, 34, k, k)`` Conv2d weight. Position ``c*|G|+g``
        holds the kernel corresponding to local output group slice ``g``
        — i.e. the GChess kernel for ``group.to_gchess[g]``."""
        order = self.group.order
        slices: List[torch.Tensor] = [
            self._apply_gchess_to_kernel(self.group.gchess_element(g))
            for g in range(order)
        ]
        stacked = torch.stack(slices, dim=1)  # (C_out, |G|, 34, k, k)
        return stacked.reshape(
            self.out_channels * order,
            self.in_channels,
            self.kernel_size,
            self.kernel_size,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.shape[1] != self.IN_CHANNELS:
            raise ValueError(
                f"LiftingConv expects {self.IN_CHANNELS} input channels, "
                f"got {x.shape[1]}"
            )
        kernel = self._build_kernel()
        if self.bias is None:
            bias = None
        else:
            bias = self.bias.repeat_interleave(self.group.order)
        return F.conv2d(x, kernel, bias, padding=self.padding)


# ---------------------------------------------------------------------------
# GConv: G -> G
# ---------------------------------------------------------------------------


class GConv(nn.Module):
    """G-equivariant convolution on G-signals (folded layout).

    Standard Cohen-Welling regular-representation G-conv. Learns ``|G|``
    independent base kernels ``K_base[d]``, ``d in range(|G|)``, each of
    shape ``(C_out, C_in, k, k)``. The full
    ``(C_out*|G|, C_in*|G|, k, k)`` Conv2d weight is built at forward
    time as

        W[c_out*|G| + g_out, c_in*|G| + g_in, :, :]
            = (g_in . K_base[group.compose(g_in, g_out)])[c_out, c_in, :, :]

    where ``g_in . K_base[d]`` is the spatial flip of ``K_base[d]``
    under the GChess element ``group.to_gchess[g_in]``. For our abelian,
    self-inverse groups this is the equivariance-preserving form: under
    both input and output regular-rep + spatial actions,
    ``GConv(g . x) = g . GConv(x)``.

    Why |G| bases (not 1)? With a single base ``K`` and
    ``W[g_in, g_out] = (g_in . g_out) . K`` the formulation is
    equivariant ONLY for the channel-permutation part of the action —
    the spatial-flip part breaks because the constraint requires an
    independent kernel slice per group-element "difference"
    ``g_in . g_out``.

    Bias is per logical output channel (broadcast across the |G| group
    copies) — equivariant under the regular representation.
    """

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        padding: int = 0,
        bias: bool = True,
        group: GroupDef = GCHESS_GROUP,
    ):
        super().__init__()
        self.group = group
        self.in_channels = in_channels   # logical
        self.out_channels = out_channels  # logical
        self.kernel_size = kernel_size
        self.padding = padding
        # |G| independent base kernels.
        self.weight = nn.Parameter(
            torch.empty(group.order, out_channels, in_channels, kernel_size, kernel_size)
        )
        for g in range(group.order):
            nn.init.kaiming_normal_(self.weight[g], nonlinearity="relu")
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter("bias", None)

    def _build_kernel(self) -> torch.Tensor:
        order = self.group.order
        big = self.weight.new_empty(
            self.out_channels * order,
            self.in_channels * order,
            self.kernel_size,
            self.kernel_size,
        )
        table = self.group.composition_table
        for g_out in range(order):
            for g_in in range(order):
                d = table[g_in][g_out]  # g_in . g_out (groups here are abelian)
                gchess_g_in = self.group.gchess_element(g_in)
                kernel_slice = _spatial_g(gchess_g_in, self.weight[d])  # (C_out, C_in, k, k)
                big[g_out::order, g_in::order] = kernel_slice
        return big

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        kernel = self._build_kernel()
        if self.bias is None:
            bias = None
        else:
            bias = self.bias.repeat_interleave(self.group.order)
        return F.conv2d(x, kernel, bias, padding=self.padding)


# ---------------------------------------------------------------------------
# GLinear: G "1x1" signal -> G "1x1" signal (used inside GSELayer)
# ---------------------------------------------------------------------------


class GLinear(nn.Module):
    """G-equivariant linear map on the regular representation.

    Maps ``(B, C_in * |G|)`` to ``(B, C_out * |G|)``. The full
    ``(C_out * |G|, C_in * |G|)`` matrix is built from a learned base
    ``(|G|, C_out, C_in)`` such that block ``(g_out, g_in)`` equals
    ``weight[group.compose(g_out, g_in)]``. This is exactly the 1x1
    GConv formula written without the spatial dim.
    """

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        bias: bool = True,
        group: GroupDef = GCHESS_GROUP,
    ):
        super().__init__()
        self.group = group
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.weight = nn.Parameter(
            torch.empty(group.order, out_channels, in_channels)
        )
        # kaiming_uniform expects 2D+ but with fan computed on last axis;
        # init each (out, in) slice independently.
        for g in range(group.order):
            nn.init.kaiming_uniform_(self.weight[g], nonlinearity="relu")
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter("bias", None)

    def _build_matrix(self) -> torch.Tensor:
        order = self.group.order
        big = self.weight.new_empty(
            self.out_channels * order,
            self.in_channels * order,
        )
        table = self.group.composition_table
        for g_out in range(order):
            for g_in in range(order):
                g_prod = table[g_out][g_in]
                big[g_out::order, g_in::order] = self.weight[g_prod]
        return big

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        matrix = self._build_matrix()
        if self.bias is None:
            bias = None
        else:
            bias = self.bias.repeat_interleave(self.group.order)
        return F.linear(x, matrix, bias)


# ---------------------------------------------------------------------------
# GBatchNorm: stats SHARED across group copies (see module docstring)
# ---------------------------------------------------------------------------


class GBatchNorm(nn.Module):
    """BatchNorm for G-signals, with stats and learnable affine SHARED
    across the |G| group copies of each logical channel.

    Implementation: reshape ``(B, C*|G|, H, W)`` to
    ``(B*|G|, C, H, W)`` so each group copy becomes a "batch element"
    inside a standard ``BatchNorm2d(C)``. Statistics are pooled over
    (batch, group, H, W) per logical channel — making BN exactly
    commute with the regular-rep permutation on the group axis. See
    the module docstring for why the statistics are shared.
    """

    def __init__(
        self,
        num_logical_channels: int,
        group: GroupDef = GCHESS_GROUP,
        eps: float = 1e-5,
        momentum: float = 0.1,
    ):
        super().__init__()
        self.group = group
        self.num_logical_channels = num_logical_channels
        self.group_size = group.order
        self.bn = nn.BatchNorm2d(num_logical_channels, eps=eps, momentum=momentum)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        b, total_c, h, w = x.shape
        c, g = self.num_logical_channels, self.group_size
        if total_c != c * g:
            raise ValueError(f"expected {c*g} channels, got {total_c}")
        # (B, C*|G|, H, W) c-major folded -> (B, C, |G|, H, W) -> (B, |G|, C, H, W) -> (B*|G|, C, H, W)
        x = x.view(b, c, g, h, w).permute(0, 2, 1, 3, 4).reshape(b * g, c, h, w)
        x = self.bn(x)
        x = x.view(b, g, c, h, w).permute(0, 2, 1, 3, 4).reshape(b, c * g, h, w)
        return x


# ---------------------------------------------------------------------------
# GSELayer: equivariant SE block
# ---------------------------------------------------------------------------


class GSELayer(nn.Module):
    """G-equivariant Squeeze-Excitation block.

    Spatial-only global average pool keeps the group dim (pooling over
    the group axis would break equivariance). Two GLinear FCs map the ``(C*|G|)`` summary through
    a bottleneck of ``(SE_C*|G|)`` and back to ``(2C*|G|)``, which we
    split into a sigmoid gate and a bias and apply element-wise.

    Equivariance: spatial pool is invariant under the spatial flip part
    of g (mean is symmetric); the regular-rep part of g permutes the
    group axis identically before and after the pool. GLinear preserves
    that permutation, ReLU and Sigmoid are channel-wise so they
    preserve it too. Element-wise ``gate * x + bias`` preserves the
    action because gate, bias, and x all transform by the same
    regular-rep on the folded channel axis.
    """

    def __init__(
        self,
        channels: int,
        se_channels: int,
        group: GroupDef = GCHESS_GROUP,
    ):
        super().__init__()
        self.group = group
        self.channels = channels  # logical
        self.se_channels = se_channels  # logical
        self.group_size = group.order
        self.fc1 = GLinear(channels, se_channels, group=group)
        self.fc2 = GLinear(se_channels, 2 * channels, group=group)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        b, cg, _, _ = x.shape
        s = x.mean(dim=[2, 3])               # (B, C * |G|) — spatial-pool only
        s = F.relu(self.fc1(s))             # (B, SE_C * |G|)
        s = self.fc2(s)                     # (B, 2C * |G|)
        # In c-major folding, the first C logical channels (= first C*|G|
        # entries) carry the gate; the next C logical channels carry the bias.
        gate = s[:, : self.channels * self.group_size]
        bias = s[:, self.channels * self.group_size:]
        gate = torch.sigmoid(gate).view(b, cg, 1, 1)
        bias = bias.view(b, cg, 1, 1)
        return gate * x + bias


# ---------------------------------------------------------------------------
# G-residual block, body, full model
# ---------------------------------------------------------------------------


class GResBlock(nn.Module):
    """G-equivariant residual block — same macro-structure as the
    baseline ResBlock, with G-equivariant primitives substituted in:

        GConv -> GBatchNorm -> ReLU -> GConv -> GBatchNorm -> GSELayer
        skip-add input -> ReLU
    """

    def __init__(
        self,
        channels: int,
        se_channels: int,
        group: GroupDef = GCHESS_GROUP,
    ):
        super().__init__()
        self.group = group
        self.conv1 = GConv(channels, channels, 3, padding=1, bias=True, group=group)
        self.bn1 = GBatchNorm(channels, group=group)
        self.conv2 = GConv(channels, channels, 3, padding=1, bias=True, group=group)
        self.bn2 = GBatchNorm(channels, group=group)
        self.se = GSELayer(channels, se_channels, group=group)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        residual = x
        out = F.relu(self.bn1(self.conv1(x)))
        out = self.bn2(self.conv2(out))
        out = self.se(out)
        out = out + residual
        return F.relu(out)


class GCNNBody(nn.Module):
    """Equivariant body: LiftingConv(34 -> filters) + GBN + ReLU,
    then ``blocks x GResBlock``. Output is a folded G-signal of shape
    ``(B, filters * |G|, 8, 8)``."""

    def __init__(
        self,
        blocks: int,
        filters: int,
        se_channels: int,
        group: GroupDef = GCHESS_GROUP,
    ):
        super().__init__()
        self.group = group
        # LiftingConv is chess-specific: it builds the |G| output group
        # slices from a single base kernel by applying each g's FULL
        # chess input action (spatial flip + sigma_c channel perm +
        # plane-30 sign flip) to the kernel. See LiftingConv's docstring
        # for the construction and equivariance derivation.
        self.input_conv = LiftingConv(
            34, filters, kernel_size=3, padding=1, bias=True, group=group
        )
        self.input_bn = GBatchNorm(filters, group=group)
        self.blocks = nn.ModuleList(
            [GResBlock(filters, se_channels, group=group) for _ in range(blocks)]
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = F.relu(self.input_bn(self.input_conv(x)))
        for block in self.blocks:
            x = block(x)
        return x  # (B, filters * |G|, 8, 8)


class GCNNChess(nn.Module):
    """Group-equivariant LCZero model — same forward interface as
    BaselineLCZero so the training/eval code is model-agnostic.

        policy_logits, value_wdl, moves_left = model(x)
        # x:             (B, 34, 8, 8)
        # policy_logits: (B, 1858)   raw logits
        # value_wdl:     (B, 3)      softmax [W, D, L]
        # moves_left:    (B, 1)      ReLU output

    Hyper-params identical to BaselineLCZero. Equivariance is enforced
    by construction at every layer; verified by
    ``metrics.equivariance.equivariance_error(model)`` for the
    relevant group.

    The ``group`` keyword selects which symmetry group the model
    enforces:

    * ``GCHESS_GROUP`` (default) — full G_chess equivariance
      (sigma_h, sigma_c, sigma_hc). |G| = 4.
    * ``SGCHESS_GROUP`` — sigma_c-only equivariance (the color-swap
      subgroup). |G| = 2; the equivariance test for this model only
      checks ``sigma_c`` (and ``equivariance_error`` would report
      non-zero errors for ``sigma_h`` and ``sigma_hc`` because the
      model is NOT equivariant under those).
    * ``FLIPGROUP_GROUP`` — sigma_h-only equivariance (the file-flip
      subgroup). |G| = 2; use ``equivariance_error_flipgroup`` (which
      tests only ``sigma_h``). The model is NOT equivariant under
      ``sigma_c`` / ``sigma_hc``. Note the value head here is fully
      INVARIANT (sigma_h does not swap W<->L), unlike the GChess /
      SGChess value heads.

    ``policy_head_style`` selects the policy-head readout:

    * ``"orbit"`` (default) — ``EquivariantPolicyHead``: group-sum +
      orbit-based gather. Works for every supported group; the cell
      assignment is unrelated to the moves' actual squares and only
      ~30/80 channels are used.
    * ``"az"`` — ``FlipGroupAZPolicyHead`` (the "fgcnn2" head):
      keeps the lc0 AZ 80-channel spatial layout (cell = from-square,
      channel = move direction/type) and achieves sigma_h-equivariance
      via the direction-mirror channel permutation. FLIPGROUP_GROUP
      only — groups containing sigma_c are rejected.
    """

    def __init__(
        self,
        blocks: int = 10,
        filters: int = 128,
        se_channels: int = 32,
        mlh_channels: int = 8,
        fc_size: int = 128,
        group: GroupDef = GCHESS_GROUP,
        policy_head_style: str = "orbit",
    ):
        super().__init__()
        self.group = group
        self.policy_head_style = policy_head_style
        self.body = GCNNBody(blocks, filters, se_channels, group=group)
        # Lazy import to break the gcnn <-> heads load-order cycle (heads
        # imports primitives from gcnn at module load).
        from .heads import (
            EquivariantPolicyHead,
            EquivariantValueHead,
            FlipGroupAZPolicyHead,
            InvariantMovesLeftHead,
        )
        if policy_head_style == "orbit":
            self.policy_head = EquivariantPolicyHead(filters, group=group)
        elif policy_head_style == "az":
            # FlipGroupAZPolicyHead itself validates group.name == "flipgroup".
            self.policy_head = FlipGroupAZPolicyHead(filters, group=group)
        else:
            raise ValueError(
                f"unknown policy_head_style {policy_head_style!r}; "
                f"expected 'orbit' or 'az'"
            )
        self.value_head = EquivariantValueHead(filters, group=group)
        self.moves_left_head = InvariantMovesLeftHead(
            filters, mlh_channels, fc_size, group=group
        )

    def forward(
        self, x: torch.Tensor
    ) -> "tuple[torch.Tensor, torch.Tensor, torch.Tensor]":
        if x.shape[1:] != (34, 8, 8):
            raise ValueError(f"GCNNChess expects (B, 34, 8, 8), got {tuple(x.shape)}")
        h = self.body(x)
        return self.policy_head(h), self.value_head(h), self.moves_left_head(h)


